mapper.delete:
delete from t_std_metemodel_detail
        where model_id = #{modelId, jdbcType=BIGINT}
        and mete_id=#{meteId,jdbcType=BIGINT}

mapper.select:
select
a.model_id,
a.mete_id,
a.custom_id as customType,
b.dict_note AS "customTypeName",
a.mete_name,
a.mete_type,
a.mete_kind,
a.analyse_type,
j.dict_note AS "analyseTypeName",
a.unit,
a.alarm_note,
a.alarm_explain,
a.alarm_type,
a.up_effect,
a.down_effect,
a.alarm_level,
a.high_limit1,
a.low_limit1,
a.high_limit2,
a.low_limit2,
a.high_limit3,
a.low_limit3,
a.high_limit4,
a.low_limit4,
a.alarm_delay,
a.alarm_cnt,
a.threshold_abs,
a.threshold_per,
a.modulus
from t_std_metemodel_detail a
left join t_dict_business b ON a.custom_id = b.dict_code
left join t_dict_business j on a.analyse_type = j.dict_code and (j.col_name = "analyse_type" or j.col_name = "defect_type")
where 1 = 1
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.mete_id = #{meteId, jdbcType=BIGINT}
 and a.custom_id = #customType, jdbcType=VARCHAR}
 and b.dict_note = #{customTypeName, jdbcType=VARCHAR}
 and a.mete_name = #{meteName, jdbcType=VARCHAR}
 and a.mete_type = #{meteType, jdbcType=VARCHAR}
and a.mete_kind = #{meteKind, jdbcType=INTEGER}
and a.analyse_type = #{analyseType, jdbcType=INTEGER}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.alarm_note = #{alarmNote, jdbcType=VARCHAR}
 and a.alarm_explain = #{alarmExplain, jdbcType=VARCHAR}
 and a.alarm_type = #{alarmType, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=REAL}
 and a.down_effect = #{downEffect, jdbcType=REAL}
 and a.alarm_level = #{alarmLevel, jdbcType=INTEGER}
 and a.high_limit1 = #{highLimit1, jdbcType=REAL}
 and a.low_limit1 = #{lowLimit1, jdbcType=REAL}
 and a.high_limit2 = #{highLimit2, jdbcType=REAL}
 and a.low_limit2 = #{lowLimit2, jdbcType=REAL}
 and a.high_limit3 = #{highLimit3, jdbcType=REAL}
 and a.low_limit3 = #{lowLimit3, jdbcType=REAL}
 and a.high_limit4 = #{highLimit4, jdbcType=REAL}
 and a.low_limit4 = #{lowLimit4, jdbcType=REAL}
 and a.alarm_delay = #{alarmDelay, jdbcType=INTEGER}
 and a.alarm_cnt = #{alarmCnt, jdbcType=INTEGER}
 and a.threshold_abs = #{thresholdAbs, jdbcType=NUMERIC}
 and a.threshold_per = #{thresholdPer, jdbcType=NUMERIC}
 and a.modulus = #{modulus, jdbcType=INTEGER}

SELECT
a.model_id,
a.mete_id,
a.custom_id as customType,
b.dict_note AS "customTypeName",
c.dict_note AS "meteTypeName",
d.device_type AS "deviceType",
e.dict_note AS "deviceTypeName",
f.dict_note AS "meteKindName",
a.mete_name,
a.mete_type,
a.mete_kind,
a.analyse_type,
l.dict_note AS "analyseTypeName",
a.unit,
a.alarm_note,
a.alarm_explain,
a.alarm_type,
k.dict_note as alarmTypeName,
a.up_effect,
a.down_effect,
a.state_zero,
a.state_one,
a.alarm_level,
j.dict_note as alarmLevelName,
a.high_limit1,
a.low_limit1,
a.high_limit2,
a.low_limit2,
a.high_limit3,
a.low_limit3,
a.high_limit4,
a.low_limit4,
a.alarm_delay,
a.alarm_cnt,
a.threshold_abs,
a.threshold_per,
a.modulus,
d.model_name
FROM
((
(
t_std_metemodel_detail a
LEFT JOIN t_dict_business b ON a.custom_id = b.dict_code
AND b.col_name = "custom_type"
)
LEFT JOIN t_dict_business c ON a.mete_type = c.dict_code
AND c.col_name = "mete_type"
)LEFT JOIN t_dict_business f on a.mete_kind=f.dict_code and  f.col_name="mete_kind")
LEFT JOIN (
t_std_metemodel d
LEFT JOIN t_dict_business e ON d.device_type = e.dict_code
AND e.col_name = "device_type"
) ON a.model_id = d.model_id
LEFT JOIN t_dict_business j ON a.alarm_level = j.dict_code
LEFT JOIN t_dict_business k ON a.alarm_type = k.dict_code
left join t_dict_business l on a.analyse_type = l.dict_code and (l.col_name = "analyse_type" or l.col_name = "defect_type")
where 1=1
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.mete_id = #{meteId, jdbcType=BIGINT}
 and a.custom_id = #{customType, jdbcType=VARCHAR}
 and b.dict_note = #{customTypeName, jdbcType=VARCHAR}
 and c.dict_note = #{meteTypeName, jdbcType=VARCHAR}
 and d.device_type = #{deviceType, jdbcType=INTEGER}
 and e.dict_note = #{deviceTypeName, jdbcType=VARCHAR}
 and a.mete_name LIKE CONCAT ('%',#{meteName, jdbcType=VARCHAR},'%')
 and a.mete_type = #{meteType, jdbcType=VARCHAR}
and a.mete_kind = #{meteKind, jdbcType=INTEGER}
and a.analyse_type = #{analyseType, jdbcType=INTEGER}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.alarm_note = #{alarmNote, jdbcType=VARCHAR}
 and a.alarm_explain = #{alarmExplain, jdbcType=VARCHAR}
 and a.alarm_type = #{alarmType, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=REAL}
 and a.down_effect = #{downEffect, jdbcType=REAL}
 and a.state_zero = #{stateZero, jdbcType=VARCHAR}
 and a.state_one = #{stateOne, jdbcType=VARCHAR}
 and a.alarm_level = #{alarmLevel, jdbcType=INTEGER}
 and a.high_limit1 = #{highLimit1, jdbcType=REAL}
 and a.low_limit1 = #{lowLimit1, jdbcType=REAL}
 and a.high_limit2 = #{highLimit2, jdbcType=REAL}
 and a.low_limit2 = #{lowLimit2, jdbcType=REAL}
 and a.high_limit3 = #{highLimit3, jdbcType=REAL}
 and a.low_limit3 = #{lowLimit3, jdbcType=REAL}
 and a.high_limit4 = #{highLimit4, jdbcType=REAL}
 and a.low_limit4 = #{lowLimit4, jdbcType=REAL}
 and a.alarm_delay = #{alarmDelay, jdbcType=INTEGER}
 and a.alarm_cnt = #{alarmCnt, jdbcType=INTEGER}
 and a.threshold_abs = #{thresholdAbs, jdbcType=NUMERIC}
 and a.threshold_per = #{thresholdPer, jdbcType=NUMERIC}
 and a.modulus = #{modulus, jdbcType=INTEGER}
ORDER BY model_id,custom_id,mete_kind
